&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Monitor regional sales performance through KPIs, performance metrics, and business analytics; provide ongoing coaching and development to maximize team effectiveness.&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
